scripts.script:
import java.util.zip.ZipFile

def metaInf = new File(project.build.outputDirectory, "META-INF")
def licensesDir = new File(metaInf, "licenses")
licensesDir.mkdirs()

def thirdPartyFile = new File(metaInf, "THIRD-PARTY.txt")
if (!thirdPartyFile.exists()) {
    log.warn("THIRD-PARTY.txt not found; skipping license texts and notices.")
    return
}
String content = thirdPartyFile.text

// Canonical texts by merged license name (lower case). A list is concatenated: GPL 2.0 plus the
// Classpath Exception. Exact names, so MIT-0 never gets the MIT text or BSD-2 the BSD-3 text.
def spdx = "https://raw.githubusercontent.com/spdx/license-list-data/main/text/"
def canonical = [
    "apache-2.0"                      : ["https://www.apache.org/licenses/LICENSE-2.0.txt"],
    "mit"                             : [spdx + "MIT.txt"],
    "mit-0"                           : [spdx + "MIT-0.txt"],
    "isc"                             : [spdx + "ISC.txt"],
    "bsd-2-clause"                    : [spdx + "BSD-2-Clause.txt"],
    "bsd-3-clause"                    : [spdx + "BSD-3-Clause.txt"],
    "gpl-2.0-with-classpath-exception": [spdx + "GPL-2.0-only.txt", spdx + "Classpath-exception-2.0.txt"],
    "gpl-2.0"                         : [spdx + "GPL-2.0-only.txt"],
    "gpl-3.0"                         : [spdx + "GPL-3.0-only.txt"],
    "lgpl-2.1"                        : [spdx + "LGPL-2.1-only.txt"],
    "lgpl-3.0"                        : [spdx + "LGPL-3.0-only.txt"],
    "agpl-3.0"                        : [spdx + "AGPL-3.0-only.txt"],
    "epl-2.0"                         : [spdx + "EPL-2.0.txt"],
    "epl-1.0"                         : [spdx + "EPL-1.0.txt"],
    "mpl-2.0"                         : [spdx + "MPL-2.0.txt"],
    "cddl-1.1"                        : [spdx + "CDDL-1.1.txt"],
    "cc0-1.0"                         : [spdx + "CC0-1.0.txt"],
    "cc-by-4.0"                       : [spdx + "CC-BY-4.0.txt"],
    "cc-by-3.0"                       : [spdx + "CC-BY-3.0.txt"],
    "cc-by-sa-4.0"                    : [spdx + "CC-BY-SA-4.0.txt"]
]
def fetch = { String url -> URI.create(url).toURL().getText("UTF-8") }
def stripHtml = { String t ->
    def lower = t.toLowerCase()
    (lower.contains("<html") || lower.contains("<!doctype")) ? t.replaceAll("(?is)<[^>]+>", " ").trim() : t
}

// What download-licenses fetched, under the plugin's own file names.
def downloaded = (licensesDir.listFiles() ?: []).findAll { it.isFile() }
def referenced = (content =~ /META-INF\/licenses\/([^\s,]+)\.txt/).collect { it[1] }.unique()
def written = [] as Set
def textProblems = []
referenced.each { String lic ->
    def target = new File(licensesDir, lic + ".txt")
    def urls = canonical[lic]
    if (urls) {
        try {
            target.text = urls.collect { fetch(it) }.join("\n\n")
        } catch (Exception e) {
            textProblems << "${lic} (could not fetch: ${e.message})"
            log.warn("Could not fetch the ${lic} text: ${e.message}")
            target.text = "(Standard ${lic} text unavailable during build; see ${urls.join(', ')})"
        }
    } else {
        def fallback = downloaded.find { it.name.toLowerCase().replace(' ', '_').startsWith(lic) }
        if (fallback) {
            target.text = stripHtml(fallback.text)
        } else {
            textProblems << "${lic} (no text)"
            log.warn("No text for license '${lic}': add it to the canonical list or src/license/licenses.xml.")
            target.text = "(License text not provided by the dependency POM)"
        }
    }
    written << target.name
}
downloaded.each { if (!written.contains(it.name)) it.delete() }

// Each component's own NOTICE, then every other license, notice or copyright file it ships,
// wherever it is in the jar: a component often bundles code under other licenses (JSch has
// jBCrypt and JZlib, the PostgreSQL driver the SCRAM libraries, grpc-netty-shaded BoringSSL),
// and those files carry the copyright lines MIT, BSD and ISC require. An Apache-2.0 text is
// named rather than repeated, but anything a LICENSE file adds after it (bundled code, often)
// is kept. ThirdPartyAttributionIT checks every such file is here.
def readEntry = { File jar, String pattern ->
    if (jar == null || !jar.isFile() || !jar.name.endsWith(".jar")) {
        return null
    }
    try {
        new ZipFile(jar).withCloseable { zip ->
            def entry = zip.entries().toList().findAll { e -> !e.isDirectory() && e.name.toUpperCase().matches(pattern) }
                    .min { it.name.length() }
            entry == null ? null : [entry.name, zip.getInputStream(entry).getText("UTF-8").trim()]
        }
    } catch (Exception e) {
        log.warn("Could not read the jar ${jar.name}: ${e.message}")
        null
    }
}
// The same rule as ThirdPartyAttributionIT.LEGAL_FILE.
def legalFile = ~/(?i)(.*\/)?(LICEN[CS]E|NOTICE|COPYING|COPYRIGHT)([._-][^\/]*)?/
def sourceFile = ~/(?i).*\.(class|java|kt|groovy|scala)/
def legalEntries = { File jar ->
    if (jar == null || !jar.isFile() || !jar.name.endsWith(".jar")) {
        return []
    }
    new ZipFile(jar).withCloseable { zip ->
        zip.entries().toList().findAll { e -> !e.isDirectory() && e.name ==~ legalFile && !(e.name ==~ sourceFile) }
                .sort { it.name }
                .collect { e -> [e.name, stripHtml(zip.getInputStream(e).getText("UTF-8")).trim()] }
    }
}
def apacheMarker = "TERMS AND CONDITIONS FOR USE, REPRODUCTION, AND DISTRIBUTION"
def apacheEnd = "limitations under the License."
def beyondApache = { String text ->
    if (!text.contains(apacheMarker)) {
        return null
    }
    int end = text.lastIndexOf(apacheEnd)
    end < 0 ? "" : text.substring(end + apacheEnd.length()).trim()
}
def copyrights = new Properties()
new File(rootDir, "src/license/copyrights.properties").withReader("UTF-8") { copyrights.load(it) }
def together = new Properties()
new File(rootDir, "src/license/licenses-apply-together.properties").withReader("UTF-8") { together.load(it) }
def missingCopyright = []
// Components that packaging adds without their being dependencies (Spring Boot's jar mode
// tools), from src/license/bundled-by-packaging.properties, copied to target/packaging-extras.
def components = project.artifacts.collect { a ->
    [groupId: a.groupId, artifactId: a.artifactId, version: a.version, file: a.file]
}
def extras = new Properties()
new File(rootDir, "src/license/bundled-by-packaging.properties").withReader("UTF-8") { extras.load(it) }
def extrasDir = new File(project.build.directory, "packaging-extras")
extras.stringPropertyNames().sort().each { String ga ->
    def (String extraGroup, String extraArtifact) = ga.split(":")
    def (String extraTitle, String extraUrl, String extraLicense) = extras.getProperty(ga).split("\\|")*.trim()
    def jar = (extrasDir.listFiles() ?: []).find { it.name ==~ /${java.util.regex.Pattern.quote(extraArtifact)}-[0-9].*\.jar/ }
    if (jar == null) {
        throw new IllegalStateException("${ga} is in bundled-by-packaging.properties but not in ${extrasDir}")
    }
    def extraVersion = jar.name.substring(extraArtifact.length() + 1, jar.name.length() - 4)
    def gav = "${extraGroup}:${extraArtifact}:${extraVersion}"
    content += "========================================================================\n" +
            "Component: ${extraTitle}\nCoordinates: ${gav}\nProject: ${extraUrl}\nLicenses: ${extraLicense}\n" +
            "License Reference: META-INF/licenses/${extraLicense.toLowerCase()}.txt\n\n--- NOTICE ---\n" +
            "[NOTICE_PLACEHOLDER_${gav}]\n[COMPONENT_LICENSE_PLACEHOLDER_${gav}]\n" +
            "========================================================================\n\n"
    components << [groupId: extraGroup, artifactId: extraArtifact, version: extraVersion, file: jar]
}
components.each { artifact ->
    def gav = "${artifact.groupId}:${artifact.artifactId}:${artifact.version}"
    def noticePlaceholder = "[NOTICE_PLACEHOLDER_${gav}]"
    def licensePlaceholder = "[COMPONENT_LICENSE_PLACEHOLDER_${gav}]"
    if (!content.contains(noticePlaceholder)) {
        return
    }
    def notice = readEntry(artifact.file, "(META-INF/)?NOTICE(\\.TXT|\\.MD)?")
    content = content.replace(noticePlaceholder, notice?.getAt(1) ?: "(No NOTICE file provided by this component)")

    def licensesLine = (content =~ /Coordinates: ${java.util.regex.Pattern.quote(gav)}\R+(?:Project: .*\R+)?Licenses: (.*)/)
    def apache = licensesLine.find() && licensesLine.group(1).split(",")*.trim().contains("Apache-2.0")
    def sections = []
    def seen = [:]
    def shipsLicense = false
    try {
        legalEntries(artifact.file).each { entry ->
            def (String entryPath, String text) = entry
            if (notice != null && entryPath == notice[0]) {
                return
            }
            if (!(entryPath ==~ /(?i)(.*\/)?NOTICE[^\/]*/)) {
                shipsLicense = true
            }
            def header = "\n--- ${entryPath} (as shipped by the component) ---\n"
            if (seen.containsKey(text)) {
                sections << header + "(The same text as ${seen[text]}.)"
                return
            }
            seen[text] = entryPath
            def extra = beyondApache(text)
            if (extra == null) {
                sections << header + (text ?: "(Empty file.)")
            } else if (extra.length() < 40) {
                sections << header + "(The Apache License 2.0: META-INF/licenses/apache-2.0.txt.)"
            } else {
                sections << header + "(The Apache License 2.0: META-INF/licenses/apache-2.0.txt; then:)\n" + extra
            }
        }
    } catch (Exception e) {
        throw new IllegalStateException("Could not read the license files of ${gav}: ${e.message}", e)
    }
    if (!apache && !shipsLicense) {
        // MIT and BSD require the copyright line, and the canonical texts only have placeholders.
        def line = copyrights.getProperty("${artifact.groupId}:${artifact.artifactId}") ?: copyrights.getProperty(artifact.groupId)
        if (line == null) {
            missingCopyright << gav
        } else {
            sections << "\n--- COPYRIGHT (from the component's published license) ---\n" + line
        }
    }
    content = content.replace(licensePlaceholder + "\n", sections ? sections.join("\n") + "\n" : "")

    // A component whose licenses each cover part of it: all apply, so none is elected.
    def allApply = together.getProperty("${artifact.groupId}:${artifact.artifactId}")
    if (allApply != null) {
        def block = ~/(Coordinates: ${java.util.regex.Pattern.quote(gav)}\R(?:(?!Coordinates: ).*\R)*?)Elected license: .*/
        def replaced = content.replaceFirst(block, { all, head -> head + "All apply: " + allApply })
        if (replaced == content) {
            throw new IllegalStateException("${gav} is in licenses-apply-together.properties but has no Elected license line")
        }
        content = replaced
    }
}
thirdPartyFile.text = content
if (missingCopyright) {
    throw new IllegalStateException("No license file in the jar and no copyright line in "
            + "src/license/copyrights.properties for: " + missingCopyright.join(", "))
}
if (textProblems && licenseStrict == "true") {
    throw new IllegalStateException("License texts missing, so this build can't be distributed: "
            + textProblems.join("; ") + ". Build with network access, or fix the source.")
}
log.info("THIRD-PARTY.txt: ${referenced.size()} license texts, notices merged.")
